"1dv":"<b>🐘 ULTIM’ORA: CVE-2026-31337 ha appena buttato giù mezza internet.</b><br>Un bug in PHP ha trasformato ogni sito WordPress-qualcosa sulla Terra in un miner di criptovalute. Il traffico eyeball cala del 30% per qualche giorno mentre il mondo applica le patch. I tuoi clienti hosting lo stanno facendo alle 3 di notte.",
