"1f1":"Un grosso ISP ha sbagliato a digitare e ha annunciato i tuoi prefissi per 18 minuti. Le scuse ci hanno messo di più. Molte reti instradano ancora il tuo traffico nel vuoto.",
"1f2":"Una città futuristica non ancora costruita, demo day a {city}",
"1f3":"<b>Un gigaprogetto vuole una demo.</b><br>{bw} per quattro giorni a {city}, per mettere in mostra una città che per ora è soprattutto rendering. Guarda la scheda Offerte.",
"1f4":"<b>Cavo del Baltico danneggiato</b><br>Una nave cargo ha trascinato l’ancora per 100 km. Non hai link su quei cavi.",
