"1f6":"<b>BGP hijack</b><br>Qualcun altro sta annunciando i tuoi prefissi. La copertura resta giù finché non si fa pulizia.",
"1f7":"<b>Cavi tagliati nel Mar Rosso</b><br>Una nave ha trascinato l’àncora su diversi cavi. Tutti danno la colpa a tutti. Per fortuna tu quei cavi non li usi.",
"1f8":"<b>Cavi tagliati nel Mar Rosso</b><br>Tuoi link sottomarini fuori uso: {n}, per circa {d} giorni, mentre i diplomatici litigano sulle navi posacavi.",
"1f9":"Chiama tutti quelli che conosci",
"1fa":"Cogentle e Goggle hanno litigato sul peering. Goggle non è raggiungibile tramite il transit di Cogentle.",
"1fb":"<b>Drizzle Electric ti ha mandato una torta IPv6.</b><br>L’hai rivenduta per $8k.",
"1fc":"Scala al loro CTO",
"1fd":"Faceplant si è stancata delle tariffe d’uso coreane e ha spostato in silenzio gli utenti coreani sui server di Hong Kong. Le pagine arrivano a passo d’uomo per tutti a Seoul. Il regolatore sta preparando una multa.",
"1fe":"<b>Faceplant ha instradato la Corea via Hong Kong.</b><br>Gli utenti di Seoul ne ricevono un quinto in meno per 20 giorni, comunque tu sia connesso.",
"1ff":"<b>Glitch lascia la Corea.</b><br>Il sito di streaming di videogiochi dice che le tariffe di rete coreane sono “proibitive” e chiude lì. Il suo traffico a Seoul si dimezza, per sempre. Gli streamer locali sono già passati ad altro.",
"1fg":"<b>Golden Week!</b><br>La domanda nella Cina continentale sale del 40% per una settimana.",
"1fh":"<b>Lite sui permessi di approdo a {city}</b><br>Due ministeri rivendicano la stessa spiaggia. Per 45 giorni lì non può approdare nessun nuovo link sottomarino.",
