"1fl":"<b>È uscita la nuova stagione di “Stranger Pings”!</b><br>La domanda degli eyeball sale del 25% per una settimana. Hai margine?",
"1fm":"<b>Meltdown del control plane ottico!</b><br>Tutte le wave in affitto in {reg} si sono spente insieme. La tua dark fiber va benissimo. Ecco perché la gente si compra la fibra.",
"1fn":"<b>Offline per decreto a {city}</b><br>Uno shutdown governativo per gli esami. Il tuo POP lì resta spento per un giorno.",
"1fo":"<b>Lite di peering!</b><br>Cogentle ha tolto il peering a Goggle per 20 giorni. Il traffico Goggle via transit Cogentle è sparito. Fai peering diretto con Goggle o usa un altro upstream.",
"1fp":"Le autorità hanno ordinato a tutte le reti di {city} di spegnersi per un giorno durante gli esami di stato. Sì, succede davvero.",
"1fq":"<b>Contributo per la banda larga rurale: +$30k</b><br>Al Ministero dei Tubi piace quello che stai facendo.",
"1fr":"<b>Sanzioni!</b><br>La Repubblica delle Scartoffie ha sanzionato il fornitore di viti preferito del produttore dei tuoi router. I ricambi arrivano lenti: per 60 giorni i crash dei router richiedono il doppio del tempo per essere riparati.",
"1fs":"<b>Esercitazione di internet sovrano</b><br>Mosca si è staccata dal resto di internet per un giorno, giusto per vedere che succede. Tutto ciò che esce dalla Russia resta al buio fino a domani.",
"1ft":"<b>Il confine si è fatto più severo.</b><br>Il packet loss transfrontaliero sale al 35% per 10 giorni. Le rotte premium se ne accorgono appena.",
"1fu":"<b>I vicini hanno litigato.</b><br>Una crisi diplomatica chiude confini e spazio aereo attorno al Qatar. Tutti i link tra Doha e Arabia Saudita o Emirati sono giù per circa {n} giorni. Fai il giro lungo, via mare.",
"1fv":"<b>Guerra commerciale sulle ottiche</b><br>Due governi si sono messi i dazi a vicenda sui laser. Le ottiche costano il 40% in più per 90 giorni.",
"1fw":"<b>I prezzi del transit sono scesi dell’8%.</b><br>Succede ogni anno. Nessuno sa dove sia il fondo.",
