"24n":"<b>L’Australia è diventata più australiana.</b><br>Il transito lì ora costa tre volte il prezzo normale, lo vendono solo gli operatori che lo vendono davvero in Australia, e Telstraya e Floptus fanno peering solo in privato, quindi le loro sessioni all’exchange sono terminate. Controlla i tuoi POP australiani.",
