"2lg":"Un exchange comunitario gestito sopra un bar del sidro. Minuscolo, economico, e ogni membro riceve un bicchiere.",
"2lh":"Un exchange commerciale più piccolo, in fondo alla strada rispetto a DE-KICKS. Pubblica i suoi prezzi su una pagina web, cosa che DE-KICKS considera un atto di guerra. Le porte arrivano senza webinar commerciale.",
