"2mo":"Porte 1.6T, un microclima tutto suo e due chip PacketOinker² per line card. Accetta wave 6.4T come 4×1.6T. Serve un muletto.",
"2mp":"Porte 3.2T e wave 12.8T consegnate come 4×3.2T. Consuma quanto un paesino e arriva con la sua cabina elettrica. Serve un muletto più grosso.",
"2mq":"Un router 3.2T al prezzo di un'auto usata. L'interfaccia web ha novecento schede, e una di queste è quella che ti serve.",
"2mr":"Uno switch bare-metal con SONiC open source. Fa risparmiare un patrimonio, finché non crasha e non c’è nessuno da chiamare.",
"2ms":"qualche dozzina di core ARM",
"2mt":"Centoquarantaquattro porte 3.2T e buffer così profondi da nasconderci una flotta intera. Si avvia ancora prima del tuo flat white. Ora anche la barba ha la barba.",
"2mu":"un ASIC misterioso",
"2mv":"Un network processor ricondizionato, firmware fermo nel tempo",
"2mw":"Un bestione con porte 800G, costruito attorno al chip di forwarding Junipurr PacketOinker™. Grugnisce a line rate. Accetta ottiche 800ZR+.",
"2mx":"si è avviato, è andato in panico per un fan tray mancante, e ha ricominciato da capo",
"2my":"Ha comprato il cappello del mago. Tunnel ovunque, segmenti mai. Porte 1.6T a prezzo di fascia media.",
"2mz":"Comprato usato su eBuy. Le ventole sembrano un motore a reazione.",
"2n":"Salta",
"2n0":"Costruito come la porta di una sauna: pesante, bollente e quasi indistruttibile. La config ormai è così gerarchica che ha una famiglia reale.",
"2n1":"Chassis economico, abbonamento eterno. Ogni porta vuole una licenza, ogni licenza vuole un server di licenze, e il server di licenze vuole una licenza.",
"2n2":"Costa poco comprarlo, tanto possederlo: chiavi di licenza per ogni porta, ogni funzione e, si dice, per le ventole. Smart Licensing telefona a casa ogni settimana.",
"2n3":"Costa meno di un pranzo e ha il doppio delle porte del Rusty. Configurarlo richiede più tempo del pranzo.",
"2n4":"network processor Fin-P6",
"2n5":"network processor Fin-P",
"2n6":"Ingegneria finlandese: indistruttibile, pignolissima, e la CLI parla solo config gerarchica. Si avvia come un’alba nordica.",
"2n7":"Config fissa, buffer profondi, barba curatissima e benda sull’occhio. Gira su EOS, l’Extensible Operating Ship. Si avvia prima che il tuo flat white al latte d’avena sia pronto, e include una shell Python che nessuno ha chiesto.",
"2n8":"quarantadue",
