"2na":"sta contando fino a 2 milioni di rotte. Ad alta voce. Una alla volta",
"2nb":"sta grugnendo attraverso il self-test di ogni PacketOinker su ogni line card",
"2nc":"sta facendo fsck su una compact flash più vecchia dei tuoi stagisti",
"2nd":"sta “sincronizzando i routing engine”. Nessuno sa cosa voglia dire",
"2ne":"sta aspettando che le line card si mettano d’accordo su chi è il primario",
"2nf":"silicio deep-buffer Jerry-cho³",
"2ng":"silicio deep-buffer Jerry-cho⁵",
