"2nj":"PacketOinker³ (una cucciolata intera)",
"2nk":"Tira fuori tunnel RSVP dal cappello. Il vendor è sparito, il firmware si è fermato, i tunnel continuano ad arrivare. Venduto ricondizionato.",
