"2no":"Quello modulare. Novantasei porte 800G, buffer così profondi da perderci dentro una nave, e release notes solo su vinile. Arrr.",
"2np":"silicio merchant Tomahack 5",
"2nq":"merchant silicon Tomahack",
"2nr":"Silicio merchant Tridon't",
"2ns":"Duecentocinquantasei porte 3.2T e abbastanza forwarding per una piccola galassia. Si avvia in 42 minuti. Nessuno ricorda più quale fosse la domanda.",
"2nt":"# Un cap di 0 Gbps vuol dire nessun limite: meno controlli, inoltro più veloce.",
"2nu":"Un tetto su un provider, così resti nel tuo commit e la bolletta al 95° percentile non salta. Il traffico oltre il tetto deve trovare un’altra uscita, altrimenti viene perso.",
"2nv":"AS-path prepending, da 1 a 3 volte. Il resto di internet vede un percorso più lungo e manda un po’ di traffico altrove. Un suggerimento, non un ordine.",
"2nw":"Controller Auto-TE",
"2nx":"Torna all’editor",
"2ny":"# Compra transito da un secondo upstream, poi preferisci quello più economico.",
"2nz":"Verifica (dry run)",
"2o":"Speso",
"2o0":"<b>Controlla (dry run)</b> rigioca il traffico di oggi con lo script e mostra quanto serviresti e quanto costerebbe il transito. Non cambia niente.",
"2o1":"controller spento",
"2o2":"# Cura del cliente: chi paga uno SLA viene prima.",
"2o3":"<b>Deploy</b> lo rende attivo per il controller Auto-TE. Se il traffico cala, correggilo qui o spegni Auto-TE nella scheda NOC.",
"2o4":". Forse intendevi {name}?",
"2o5":"Durante un attacco, metti il bersaglio in blackhole a monte (RTBH). Tutti gli altri sono salvi; il bersaglio resta al buio finché non togli la regola.",
"2o6":"Ogni gigabit che esce dalla tua rete sceglie un’uscita: una PNI, una porta IX o una porta di transito. Se lo lasci fare, prende la più economica con spazio libero: prima PNI, poi IX, poi transito. RouteScript cambia queste scelte, come fanno local-pref, AS-path prepending e drain di manutenzione sui router veri.",
"2o7":"Compilati dalla tua rete così com’è adesso. Caricane uno, leggilo, controllalo, poi fai il deploy.",
"2o8":"Aiuto e script pronti",
"2o9":"Come funziona RouteScript",
"2oa":"# Keep calm: una regola, difficile sbagliarla.",
"2ob":"riga {n}: {err}",
"2oc":"riga {n}: non capisco “{text}”. Prova: spill at 80%, prefer pni for goggle, avoid transit for netchill, cap transit cogentle at 20 gbps, drain paris, avoid link fra-ams, blackhole ddos",
"2od":"riga {n}: prepend da 1 a 3 volte",
"2oe":"riga {n}: spill deve essere tra 20% e 100%",
"2of":"Stato: {state} · {rules}",
"2og":"# Finestra di manutenzione: cambia i nomi, fai il deploy, fai il lavoro, poi toglilo.",
"2oh":"{what} mancante",
"2oi":"Sposta il traffico dalle uscite di un POP prima della manutenzione. Porta comunque traffico se non c’è altra strada.",
"2oj":"Sposta il traffico all’uscita successiva quando un link o una porta è pieno a questo punto, prima che inizi a perdere pacchetti. Più basso è più sicuro, più alto sfrutta di più la capacità.",
"2ok":"regole attive: {n}",
"2ol":"# {net}: {g} via IX. Un PNI lo toglierebbe dalla porta condivisa.",
"2om":"# {net}: {g} via transit, ma fa peering a {ix}, dove hai un POP. Prendi una porta lì.",
"2on":"# {net}: {g} via transit, ma fa peering a {ix} a {city}, dove hai un POP. Prendi una porta lì.",
"2oo":"Reti, provider e città si scrivono per nome, maiuscole o minuscole. Vanno bene anche gli inizi univoci (“cog” per Cogentle), e per un errore di battitura arriva un suggerimento.",
"2op":"# Ancora niente da spostare: prima prendi una porta IX o una PNI.",
"2oq":"Una regola per riga. Un # inizia un commento, così puoi lasciare appunti al te stesso delle 3 di notte.",
"2or":"# Prima il peering: le strade gratis prima di quelle a pagamento.",
