"2r6":"1.6T su ogni tratto da Miami a Madrid e da Lisbona a Lagos, e 100 Gbps serviti",
"2r7":"90 giorni di fila con il 99.5% della domanda servita",
"2r8":"99% di copertura e 150 Gbps serviti",
"2r9":"Un percorso da Città del Capo al Cairo, con Lagos e Nairobi anche loro sulla tua rete, e 150 Gbps serviti",
"2ra":"Un percorso da Los Angeles a Sydney con 1.6T su ogni tratta, un percorso da Los Angeles a Tokyo e 150 Gbps serviti",
"2rb":"Un percorso da Marsiglia a Singapore, e 80 Gbps tra l’Asia e il resto della tua rete per 30 giorni di fila",
"2rc":"Amsterdam, capitale europea dell’hosting, in piena stagione delle botnet. Ogni tostapane smart, baby monitor e frigo mai aggiornato della Terra ha scelto da che parte stare, e non è la tua. Un’ondata ogni pochi giorni, sempre più spesso nei terabit, mentre tutto il resto continua a rompersi. Parti con l’attrezzatura più grossa già sbloccata, e ti servirà.",
"2rd":"Banda larga a Sydney, Melbourne, Brisbane, Adelaide e Perth, due cavi diversi verso l’estero, e 500 Gbps serviti",
"2re":"Dal Capo al Cairo",
"2rf":"Città del Capo. Costruisci una rete attraverso l’Africa: ogni confine vuole il suo permesso, e i generatori fanno parte della rete.",
"2rg":"Cogentle e Goggle non si parlano, e stavolta è per sempre. Compra il transit economico, se hai il coraggio.",
"2rh":"Bogotá, Lima, Santiago e São Paulo collegate a Panama City, e 150 Gbps serviti",
"2ri":"Servi il Carnaval per intero",
"2rj":"Ogni cavo nel Mar Rosso è tagliato, e anche il salto verso l’Egitto. Fai parlare Marseille con Singapore lo stesso: girando intorno all’Africa, via terra o dall’altra parte del pianeta.",
"2rk":"Ogni IX è gestito da DE-KICKS",
"2rl":"Gli eyeball crescono il 50% più in fretta",
"2rm":"Fibra in cantina",
"2rn":"Gangnam Style Peering",
"2ro":"Reggi 20 inondazioni, 5 sopra 1 Tbps: ogni bersaglio al 97% o meglio, nessun altro colpito",
"2rp":"Honolulu, in mezzo al Pacifico. I cavi tra le Americhe, l’Asia e l’Australia sono così lunghi che una wave ci porta solo 400G o 800G. Ferma la luce su un’isola, falla ripartire da zero, e ogni tratta diventa più corta e più veloce. Inizi con l’hardware 1.6T già sbloccato.",
"2rq":"Accento medio-atlantico",
"2rr":"Solo Spätzle-IX",
"2rs":"Ordine e Progresso",
"2rt":"Ponta Delgada, nelle Azzorre, a metà dell’Atlantico. Dalla Florida alla Spagna è appena troppo lungo per un’onda da 1.6T: in linea diretta porta 1.2T. Approda sulle isole in mezzo, fai ripartire la luce e ogni tratto va a 1.6T o più. Da Lisbona a Lagos l’1.6T arriva in un colpo solo, ma a caro prezzo: le Canarie costano meno. Parti con l’attrezzatura da 1.6T sbloccata.",
"2ru":"Porte su 15 exchange IX.brrr che la tua dorsale collega a São Paulo, una delle quali a Manaus, e 200 Gbps serviti",
"2rv":"Raggiungi il 50% di internet e servi 300 Gbps",
"2rw":"Crisi nel Mar Rosso",
"2rx":"Rio da zero. Il Carnaval comincia tra 90 giorni e vuole 400 Gbps per cinque giorni di fila. Il mondo intero sta guardando.",
"2ry":"<b>Modalità sandbox</b><br>Un miliardo di dollari e tutto sbloccato. Caos: {chaos}. Costruisci l’internet che hai sempre sognato, e tieni una ruspa di scorta a portata di mano.",
"2rz":"<b>Modalità sandbox</b><br>Un miliardo di dollari, tutto sbloccato e non si rompe mai niente. Costruisci l’internet che hai sempre sognato.",
"2s":"Troppo lento: trova una strada più veloce.",
"2s0":"São Paulo. Il Brasile è un continente: quaranta exchange IX.brrr, migliaia di provedores e l’Amazzonia tra te e il nord.",
"2s1":"Seul, dove paga chi invia. Ogni Gbps che un carrier consegna in Corea ti costa una tassa «sender pays» oltre alla bolletta del transit, i tre incumbent parlano solo tramite un PNI a pagamento, il gigabit di casa costa quanto un bibimbap e gli utenti coreani notano ogni millisecondo. Il transit a Tokyo è economico, se i tuoi clienti reggono il viaggio.",
"2s2":"{g} Gbps serviti, Seul servita bene ({q}%), 99% di copertura e un utile mensile",
"2s3":"Stagione degli squali: tagli sottomarini due volte più probabili",
"2s4":"Parti da Panama City. Niente attraversa il Darién Gap via terra, e le Ande sono d’intralcio a tutto il resto.",
"2s5":"Parti da Stuttgart, dove nessuno vende transit. Raggiungi internet solo con peering, PNI, cache e la tua fibra. Niente transit, da nessuna parte, mai.",
"2s6":"Parti con soli $100k",
"2s7":"Sydney, 2013. Il Toilet Paper Group ha portato la sua fibra nelle cantine dei condomini, e la rete nazionale ha gridato al cherry-picking. Tocca a te: salta la Nearly Broadband Network, paga il contributo e arriva per primo.",
"2s8":"Tallinn, dove nessuno vende transit: la tua internet è al di là del mare. Le navi trascinano le ancore sui cavi del Baltico tre volte più spesso del solito.",
"2s9":"La lite Cogentle",
