"ops.mood_annie":"Annie ha risposto a tre domande prima che tu le facessi, dalla scrivania più vicina.",
"ops.mood_broke":"{name} ha già la lista della spesa per quando arriva il budget del mese prossimo.",
"ops.mood_busy":"{name} ha avuto una settimana piena ed è alla terza bevanda energetica.",
"ops.mood_kevin":"Kevin dice che nel 2001 era più tranquillo. Non lo era.",
"ops.mood_new":"{name} ha trovato la macchinetta del caffè e la CLI, in quest'ordine. Pronto quando vuoi.",
