"ops.o_caches":"Accetta cache gratuite",
"ops.o_caches_d":"Monta ogni cache gratuita che una rete offre, appena il suo traffico in quella città supera una soglia.",
"ops.o_decom":"Ritira i piccoli link paralleli",
"ops.o_decom_d":"Quando un link più grande tra due città è attivo, restituisci le wave piccole che non servono più. Mai una che un cliente noleggia o da cui dipende.",
"ops.o_ix":"Peering su ogni IX",
"ops.o_ix_d":"Ogni settimana: entra nei route server e chiedi il peering a ogni membro disponibile su ciascuna delle tue porte di exchange.",
"ops.o_optics":"Accendi più fibra",
"ops.o_optics_d":"Aggiungi ottiche alla dark fiber che scotta e accendi la fibra nuova il giorno della consegna.",
"ops.o_pni":"PNI con i grandi",
"ops.o_pni_d":"Ogni settimana: ordina un PNI con ogni rete disponibile che manda abbastanza traffico nei tuoi POP, alla taglia minima di ciascuna rete.",
"ops.o_ports":"Margine sulle porte di peering",
"ops.o_ports_d":"Tieni le porte PNI e IX sopra un multiplo del traffico di oggi: una porta singola in un POP con più router ne riceve una seconda in LAG, tutte le altre passano a una porta più grande.",
"ops.o_repair":"Accelera le riparazioni",
"ops.o_repair_d":"Paga la riparazione urgente di ogni guasto che ce l'ha, finché il budget regge.",
"ops.o_routers":"Router sempre avanti",
"ops.o_routers_d":"Aggiungi un router, o passa alla generazione successiva dove un secondo router regge il traffico, quando carico o porte superano una soglia.",
"ops.o_sales":"Gestisci le vendite",
"ops.o_sales_d":"Firma le offerte i cui requisiti sono soddisfatti con capacità in avanzo, e rifiuta quelle che pagano troppo poco.",
"ops.o_transit":"Margine di transit",
"ops.o_transit_d":"Tieni il transit di ogni POP sopra un multiplo del suo picco a 30 giorni: un membro LAG in più, o una porta più grande.",
