"oq":"Tonga è appesa a un solo cavo dalle Figi. Nel 2022 un vulcano sottomarino l’ha tranciato e il paese è rimasto offline per settimane.",
"or":"La capitale di Trinidad, all’estremità sud della catena di isole e a pochi chilometri dal Venezuela.",
"os":"Dodicimila persone e il loro primo cavo, approdato ad agosto 2025 sulla strada da Tarawa a Pohnpei.",
"ot":"A venti minuti da tutto, tranne che da qualsiasi altro posto.",
"ou":"Città gemelle, un solo exchange e passerelle tra i palazzi: anche Minneapolis fa peering qui, e a gennaio nessuno esce a giuntare una fibra.",
"ov":"Due milioni di persone in mezzo alla foresta pluviale, con una zona franca piena di fabbriche. La fibra segue i fiumi, e quando si rompe la squadra di riparazione parte in barca.",
"ow":"Due exchange rivali, uno all’università tecnica e uno commerciale, e quasi tutte le reti slovacche stanno su entrambi.",
"own_cable.a_fishing_fleet_is_trawling_exactly":"Una flotta di pescherecci sta strascicando proprio dove devi posare.",
"own_cable.a_whale_has_parked_on_the":"Una balena si è parcheggiata sul percorso e non si sposta.",
"own_cable.storm_season_the_ship_is_sheltering":"Stagione delle tempeste. La nave è al riparo in porto, a giocare a carte.",
"own_cable.the_cable_ship_s_coffee_machine":"La macchina del caffè della nave posacavi si è rotta. Senza caffè non lavora nessuno.",
"own_cable.the_crew_fished_out_somebody_else":"L’equipaggio ha ripescato per sbaglio il cavo di qualcun altro e deve rimetterlo giù.",
"own_cable.the_seabed_survey_found_an_old":"Il rilievo del fondale ha trovato una vecchia mina. Una piccola, attentissima deviazione.",
"ox":"Tifoni, terremoti e tantissima gente sempre online.",
"oy":"Gli ingegneri di rete ucraini hanno tenuto in piedi internet tra blackout e cose molto peggiori. Generatori, fibra di scorta e ridondanza su tutto qui sono la norma, e la scena del peering è notoriamente tosta.",
"oz":"Università, biotech e un carrier hotel che è sopravvissuto alla maggior parte dei suoi carrier.",
"p":"{city} resta al buio",
"p0":"Uruguay: fibra in quasi ogni casa, un portatile per ogni scolaro, e una telco di stato che gestisce quasi tutto.",
"p1":"Sempre online e servita male dal mare: in qualsiasi momento almeno uno dei suoi cavi sottomarini è rotto.",
"p2":"La capitale della Virginia, dove i cavi transatlantici di Virginia Beach arrivano nell’entroterra fino a un exchange neutrale: una porta per l’Europa più tranquilla di Ashburn.",
"p3":"Il calore di scarto finisce dritto nelle terme accanto.",
"p4":"Quando nel 2018 il suo unico cavo è stato tagliato, la Mauritania è rimasta quasi del tutto offline per due giorni.",
"p5":"Quando nel 2025 è arrivato il cavo, tutto il paese ha avuto internet gratis per un giorno per festeggiare.",
"p6":"Dove si incontrano Brasile, Argentina e Paraguay, accanto a cascate gigantesche e a una diga ancora più grande. L’energia costa poco, le pratiche doganali no.",
"p7":"Dove approdano i cavi dell’Africa orientale, che poi salgono in treno fino a Nairobi.",
"p8":"Dove i cavi del Sud America approdano davvero. Europa, Africa e USA arrivano a riva qui, poi fanno un lungo backhaul verso sud.",
"p9":"Dove approdano i cavi atlantici per il sud dell’Africa. Pinguini sulla spiaggia, distacchi programmati sulla rete elettrica.",
"pa":"Case bianche che salgono dal Mediterraneo. I cavi vanno a nord verso Marsiglia, e anche gran parte del traffico.",
"pb":"Collegata in quattro modi per meno di un milione di persone: EASSy, 2Africa e due cavi corti verso Mayotte.",
