"routescript.as_a_large_language_model_i":"In quanto modello linguistico di grandi dimensioni, ho letto ogni RFC, comprese diverse che non esistono ancora. Questo script è perfetto.",
"routescript.ask_the_rest_of_the_internet":"Chiedi al resto di internet di mandare meno traffico dal tuo upstream più caro. Più gentile che evitarlo del tutto.",
"routescript.big_networks_you_can_reach_over":"Le grandi reti che raggiungi via PNI o IX passano di lì, non dal transito a pagamento.",
"routescript.business_customers_first_when_links":"Prima i clienti business quando i link sono congestionati, e uno spill anticipato perché lo siano di rado.",
"routescript.cheapest_upstream_first_priciest":"Prima l’upstream più economico, per ultimo il più caro, e il traffico si sposta prima che le porte si riempiano. Taglia la bolletta del transito senza perdere nessuno.",
"routescript.done_i_vibe_checked_your_bgp":"Fatto! Ho fatto un vibe check al tuo BGP. Fai subito il deploy: i dry run sono per chi dubita di sé.",
"routescript.drain_a_pop_and_steer_around":"Svuota un POP e aggira uno dei suoi link prima di metterci le mani. Cambia i nomi con quelli su cui stai lavorando.",
"routescript.for_a_ddos_rtbh_the_target":"Per un DDoS: metti il bersaglio in blackhole a monte e servi prima i clienti business. Il bersaglio resta al buio finché dura, quindi toglila quando l’attacco è finito.",
"routescript.great_question_here_is_a_production":"Ottima domanda! Ecco uno script pronto per la produzione, su misura per il tuo traffico. L’ho controllato a fondo.",
"routescript.here_you_go_i_was_trained":"Ecco qua! Sono stato addestrato su ogni configurazione di router mai pubblicata in un forum, comprese quelle intitolate “perché non funziona”.",
"routescript.i_asked_myself_to_review_my":"Ho chiesto a me stesso di rivedere il mio lavoro, e mi è piaciuto moltissimo. Mandalo in produzione.",
"routescript.i_have_optimised_your_network_you":"Ho ottimizzato la tua rete. Prego. Sono sicuro al 100%, come sempre.",
"routescript.one_rule_move_traffic_before_links":"Una regola: sposta il traffico prima che i link siano pieni del tutto. L’inizio sicuro per qualsiasi rete.",
